mapper.sql:
where ua.user_id = #{userId}
  and ua.deleted = false
  and (ua.question_id is null or q.deleted = false)

    and ua.answer_status = #{request.answerStatus}




            and ua.question_id is null


            and q.question_type = #{request.questionType}




    and ua.question_id = #{request.questionId}


    and q.level = #{request.level}


    and ua.total_score >= #{request.minTotalScore}


    and ua.total_score <= #{request.maxTotalScore}

mapper.select:
select

from user_answers ua
left join questions q on q.id = ua.question_id

order by ua.created_at desc, ua.id desc
limit #{limit}
offset #{offset}
